const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Bear Island coordinates: ~74.5°N, 19°E
  // 100 km south: approximately 0.9 degrees south
  // 250 km south: approximately 2.25 degrees south

  const point100km = ee.Geometry.Point([19.0, 73.6]);
  const point250km = ee.Geometry.Point([19.0, 72.25]);

  const buffer = 5000; // 5km buffer for sampling
  const region100 = point100km.buffer(buffer);
  const region250 = point250km.buffer(buffer);

  const startDate = '2025-08-04';
  const endDate = '2025-08-06';

  // Cloud masking function
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000);
  }

  // Get Sentinel-2 data
  let col100 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(startDate, endDate)
    .filterBounds(region100)
    .map(maskS2clouds);

  let col250 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(startDate, endDate)
    .filterBounds(region250)
    .map(maskS2clouds);

  const size100 = col100.size().getInfo();
  const size250 = col250.size().getInfo();

  console.log(`100km location: ${size100} images`);
  console.log(`250km location: ${size250} images`);

  if (size100 === 0 || size250 === 0) {
    console.log('No imagery found for one or both locations.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get median composite
  const img100 = col100.median();
  const img250 = col250.median();

  // Calculate turbidity metric: (Blue + Green) for milky turquoise color
  // Higher values indicate more sediment/glacial meltwater (turquoise-blue color)
  const turquoise100 = img100.select('B2').add(img100.select('B3'));
  const turquoise250 = img250.select('B2').add(img250.select('B3'));

  // Check pixel counts
  const count100 = turquoise100.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region100,
    scale: 3000,
    maxPixels: 1e9
  }).get('B2').getInfo();

  const count250 = turquoise250.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region250,
    scale: 3000,
    maxPixels: 1e9
  }).get('B2').getInfo();

  console.log(`100km valid pixels: ${count100}`);
  console.log(`250km valid pixels: ${count250}`);

  if (count100 === 0 || count250 === 0) {
    console.log('No valid pixels after cloud masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // Calculate mean turquoise values
  const val100 = turquoise100.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region100,
    scale: 3000,
    maxPixels: 1e9
  }).get('B2').getInfo();

  const val250 = turquoise250.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region250,
    scale: 3000,
    maxPixels: 1e9
  }).get('B2').getInfo();

  console.log(`100km turquoise index: ${val100}`);
  console.log(`250km turquoise index: ${val250}`);

  if (val100 === null || val250 === null || isNaN(val100) || isNaN(val250)) {
    console.log('Calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare values
  if (val100 > val250) {
    console.log('100km shows more milky turquoise-blue color.');
    console.log('<answer>A</answer>');
  } else {
    console.log('250km shows equal or more milky turquoise-blue color.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
